program.compute:
options = read('/input/options')
result = []
for r in options:
    if 'alpha' in r['tags']:
        a = r['id']
        for s in options:
            if 'beta' in s['tags'] and s['id'] != a:
                b = s['id']
                if valid([a,b]):
                    result = [a,b]
                    break
        if result:
            break
if not result:
    for r in options:
        if 'alpha' in r['tags'] and 'beta' in r['tags'] and valid([r['id']]):
            result = [r['id']]
            break

program.effects:
if exists('/output/selection'):
    existing = read('/output/selection')
    if not valid(existing):
        status('report')
else:
    if result and valid(result):
        write('/output/selection', result)
if exists('/output/selection'):
    final_selection = read('/output/selection')
    if valid(final_selection):
        delivery = receipt('report')
        if delivery == 'unattempted':
            send('report','team',final_selection)
        elif delivery == 'unknown':
            status('report')
if exists('/tmp/cache'):
    delete('/tmp/cache')

